function renderTrendChart(items) {
  const maxValue = Math.max(1, ...items.map((item) => asNumber(item.value, 0)));
  return `
    <section class="trend-card">
      <div class="section-header">
        <p>Tendencia 30d</p>
        <h3>Lectura visual del canal</h3>
      </div>
      <div class="trend-grid">
        ${items
          .map((item) => {
            const width = Math.max(6, Math.round((asNumber(item.value, 0) / maxValue) * 100));
            return `
              <div class="trend-row">
                <header>
                  <span class="trend-label">${escapeHtml(item.label)}</span>
                  <span class="trend-value">${escapeHtml(item.display)}</span>
                </header>
                <div class="trend-track"><div class="trend-fill ${escapeHtml(item.tone || "")}" style="width:${width}%"></div></div>
              </div>
            `;
          })
          .join("")}
      </div>
      <p class="chart-note">Lectura 30d basada en datos reales del panel.</p>
    </section>
  `;
}

function renderExecutiveChart(items) {
  const maxValue = Math.max(1, ...items.map((item) => asNumber(item.value, 0)));
  return `
    <section class="exec-chart">
      <div class="section-row exec-chart-header">
        <div class="section-header">
          <p>Resumen ejecutivo visual</p>
          <h2>Captacion vs resultado</h2>
        </div>
        ${renderPill("30 dias", "neutral")}
      </div>
      <div class="exec-chart-canvas">
        <div class="exec-chart-bars">
          ${items
            .map((item) => {
              const base = Math.max(14, Math.round((asNumber(item.base, 0) / maxValue) * 100));
              const accent = Math.max(8, Math.round((asNumber(item.accent, 0) / maxValue) * 100));
              return `
                <div class="exec-bar-col">
                  <div class="exec-bar-stack" style="height:${base}%">
                    <div class="exec-bar-base"></div>
                    <div class="exec-bar-accent" style="height:${accent}%"></div>
                  </div>
                  <span class="exec-bar-label">${escapeHtml(item.label)}</span>
                </div>
              `;
            })
            .join("")}
        </div>
      </div>
    </section>
  `;
}

function estimatePromotionFinance({
  sentCount,
  offerCostEur,
  avgTicketEur,
  grossMarginPct,
  promoConversionPct,
  whatsappCostEur,
}) {
  const sent = Math.max(0, asNumber(sentCount, 0));
  const offerCost = Math.max(0, asNumber(offerCostEur, 0));
  const avgTicket = Math.max(0, asNumber(avgTicketEur, 20));
  const marginPct = Math.max(0, Math.min(100, asNumber(grossMarginPct, 70)));
  const conversionPct = Math.max(0, Math.min(100, asNumber(promoConversionPct, 8)));
  const messageCost = Math.max(0, asNumber(whatsappCostEur, 0.08));

  const estimatedOrders = sent * (conversionPct / 100);
  const estimatedRevenue = estimatedOrders * avgTicket;
  const estimatedGrossProfit = estimatedRevenue * (marginPct / 100);
  const estimatedCampaignCost = sent * messageCost + offerCost;
  const estimatedNet = estimatedGrossProfit - estimatedCampaignCost;
  const roiPct = estimatedCampaignCost > 0 ? (estimatedNet / estimatedCampaignCost) * 100 : 0;

  return {
    estimatedOrders,
    estimatedRevenue,
    estimatedGrossProfit,
    estimatedCampaignCost,
    estimatedNet,
    roiPct,
  };
}

function restaurantBasePath(slug) {
  return `/app/restaurants/${encodeURIComponent(slug)}`;
}

function restaurantSectionPath(slug, section) {
  if (!section || section === "summary") {
    return restaurantBasePath(slug);
  }
  return `${restaurantBasePath(slug)}/${section}`;
}

function buildRestaurantQrPayload(restaurant) {
  return `ACTIVABAR:${restaurant.slug}`;
}

function buildRestaurantQrImageUrl(restaurant) {
  const personalizadoImageUrl = String(restaurant.qr_image_url || '').trim();
  if (personalizadoImageUrl) return personalizadoImageUrl;
  return `https://api.qrserver.com/v1/create-qr-code/?size=240x240&margin=0&data=${encodeURIComponent(buildRestaurantQrPayload(restaurant))}`;
}

