function isAppHostname(hostname = "") {
  const value = String(hostname || "").toLowerCase();
  return (
    value === "app.activabar.es" ||
    value.startsWith("app.") ||
    value === "activabar-api.onrender.com" ||
    value.endsWith(".onrender.com")
  );
}

