function promotionActionButtons({ restaurant, promotion, canManage = true }) {
  if (!canManage) return "";
  const base = `${restaurantBasePath(restaurant.slug)}/promotions/${promotion.id}`;
  const items = [];

  if (!promotion.archived_at && isPromotionDraft(promotion)) {
    items.push(`<a class="btn secondary" href="${base}/edit">Editar borrador</a>`);
  }

  if (!promotion.archived_at) {
    items.push(renderPostButton(`${base}/dispatch`, "Enviar ahora", "primary"));
  }

  items.push(renderPostButton(`${base}/duplicate`, "Duplicar", "secondary"));

  if (promotion.archived_at) {
    return items.join("");
  }

  if (isPromotionDraft(promotion)) {
    items.push(renderPostButton(`${base}/delete`, "Borrar", "secondary"));
  } else {
    items.push(renderPostButton(`${base}/archive`, "Archivar", "secondary"));
  }

  return items.join("");
}

