async function getWebSession(req) {
  const cookies = parseCookies(req.headers.cookie || "");
  const token = cookies[env.sessionCookieName];
  if (!token) return null;
  return findActiveSessionByToken(token);
}

async function requireWebAuth(req, res, next) {
  try {
    const session = await getWebSession(req);
    if (!session) {
      return res.redirect("/login");
    }
    req.auth = session;
    return next();
  } catch (error) {
    return next(error);
  }
}

function filterRestaurantsForOperator(restaurants, operator) {
  if (canManageAllRestaurants(operator)) {
    return restaurants;
  }
  const ids = operator.restaurant_ids || operator.restaurantIds || [];
  return restaurants.filter((restaurant) => ids.includes(Number(restaurant.id)));
}

async function loadRestaurantOrRedirect(slug, operator, res) {
  const restaurant = await getRestaurantBySlugWithSecrets(slug);
  if (!restaurant) {
    res.redirect("/app?error=Restaurante%20no%20encontrado.");
    return null;
  }
  if (!canAccessRestaurant(operator, restaurant.id)) {
    res.redirect("/app?error=No%20tienes%20acceso%20a%20ese%20restaurante.");
    return null;
  }
  return restaurant;
}

router.get("/", async (req, res, next) => {
  try {
    const session = await getWebSession(req);
    if (isAppHostname(req.hostname)) {
      return res.redirect(session ? "/app" : "/login");
    }
    return res.type("html").send(
      renderMarketingLanding({
        demoHref: "/demo",
        dashboardHref: session ? "/app" : "/login",
      })
    );
  } catch (error) {
    return next(error);
  }
});

router.get("/demo", (req, res) => {
  const successMessage = String(req.query.success || "").trim();
  const errorMessage = String(req.query.error || "").trim();
  const homeHref = isAppHostname(req.hostname) ? "https://activabar.es" : "/";
  res.type("html").send(
    renderDemoRequestPage({
      formAction: "/demo",
      homeHref,
      errorMessage,
      successMessage,
    })
  );
});

router.post("/demo", async (req, res, next) => {
  try {
    const payload = {
      name: String(req.body.name || "").trim(),
      businessName: String(req.body.businessName || "").trim(),
      email: String(req.body.email || "").trim().toLowerCase(),
      phone: String(req.body.phone || "").trim(),
      city: String(req.body.city || "").trim(),
      locationsCount: String(req.body.locationsCount || "").trim(),
      message: String(req.body.message || "").trim(),
      companyWebsite: String(req.body.companyWebsite || "").trim(),
    };

    if (payload.companyWebsite) {
      return res.redirect("/demo?success=Solicitud%20recibida.");
    }

    if (!payload.name || !payload.businessName || !payload.email || !payload.phone) {
      return res.status(400).type("html").send(
        renderDemoRequestPage({
          formAction: "/demo",
          homeHref: isAppHostname(req.hostname) ? "https://activabar.es" : "/",
          errorMessage: "Faltan datos obligatorios.",
          values: payload,
        })
      );
    }

    const locationsCount = payload.locationsCount
      ? Number.parseInt(payload.locationsCount, 10)
      : null;

    const demoRequest = await createDemoRequest({
      name: payload.name,
      businessName: payload.businessName,
      email: payload.email,
      phone: payload.phone,
      city: payload.city,
      locationsCount:
        Number.isInteger(locationsCount) && locationsCount > 0 ? locationsCount : null,
      message: payload.message,
      source: req.hostname || "landing",
    });

    logger.info("demo_request.created", {
      demoRequestId: demoRequest.id,
      email: demoRequest.email,
      businessName: demoRequest.business_name,
      source: demoRequest.source,
    });

    try {
      const notification = await sendDemoRequestNotification(demoRequest);
      if (notification.skipped) {
        logger.warn("demo_request.notification_skipped", {
          demoRequestId: demoRequest.id,
          reason: notification.reason || "unknown",
        });
      } else {
        logger.info("demo_request.notification_sent", {
          demoRequestId: demoRequest.id,
          to: "configured_recipient",
        });
      }
    } catch (error) {
      logger.warn(
        "demo_request.notification_failed",
        {
          demoRequestId: demoRequest.id,
          email: demoRequest.email,
          businessName: demoRequest.business_name,
        },
        error
      );
    }

    return res.redirect("/demo?success=Solicitud%20enviada.%20Te%20contactare%20pronto.");
  } catch (error) {
    return next(error);
  }
});

